package com.dorm.platform.stay.service;

import com.dorm.platform.common.*;
import com.dorm.platform.security.*;
import com.dorm.platform.notice.service.NoticeService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.*;
import java.util.*;
import static com.dorm.platform.common.Input.*;
import static com.dorm.platform.common.BizException.require;

@Service
public class StayService {
 private final SqlStore db; private final DataScope scope; private final NoticeService notice;
 public StayService(SqlStore db,DataScope scope,NoticeService notice){this.db=db;this.scope=scope;this.notice=notice;}
 @Transactional public void lockBatch(CurrentUser u,long batchId){role(u,"DORM_MANAGER");for(var a:db.rows("SELECT application_id FROM stay_application WHERE batch_id=? AND current_status='PENDING_REVIEW' AND "+scope.buildingFilter(u,"building_id")+" ORDER BY application_id FOR UPDATE",batchId))lock(u,id(a.get("application_id")),true);}
 public List<Map<String,Object>> batches(CurrentUser u){
  role(u,"STUDENT","DORM_MANAGER","ADMIN");List<Map<String,Object>> rows;
  if(u.role().equals("STUDENT"))rows=db.rows("SELECT b.*,r.building_id,r.application_deadline student_deadline,r.auto_lock FROM stay_batch b JOIN stay_building_rule r ON r.batch_id=b.batch_id JOIN v_accommodation_current a ON a.building_id=r.building_id WHERE a.student_id=? AND b.current_status='OPEN' ORDER BY b.batch_id DESC",u.id());
  else if(u.role().equals("DORM_MANAGER"))rows=db.rows("SELECT * FROM stay_batch WHERE current_status='OPEN' ORDER BY batch_id DESC");
  else rows=db.rows("SELECT * FROM stay_batch WHERE current_status IN ('DRAFT','OPEN') AND open_end_date>=CURRENT_DATE() ORDER BY batch_id DESC");
  for(var row:rows)row.put("materials",db.rows("SELECT f.file_id,f.original_name,f.content_type,f.size_bytes FROM stay_batch_material m JOIN file_resource f ON f.file_id=m.file_id WHERE m.batch_id=? ORDER BY m.material_id",row.get("batch_id")));
  return rows;
 }
 public List<Map<String,Object>> allBatches(CurrentUser u){
  role(u,"ADMIN");
  return db.rows("SELECT batch_id,batch_name,academic_year,vacation_type,current_status FROM stay_batch ORDER BY academic_year DESC,batch_id DESC");
 }
 public List<Map<String,Object>> dashboardStats(CurrentUser u){
  role(u,"STUDENT","DORM_MANAGER","ADMIN");String filter=switch(u.role()){
   case "STUDENT" -> "a.student_id="+u.id();
   case "DORM_MANAGER" -> scope.buildingFilter(u,"a.building_id");
   default -> "1=1";
  };
  return db.rows("SELECT a.current_status status,COUNT(*) total FROM stay_application a WHERE "+filter+" GROUP BY a.current_status ORDER BY total DESC,a.current_status");
 }
 public List<Map<String,Object>> monthlyStats(CurrentUser u){
  role(u,"ADMIN");
  return db.rows("WITH RECURSIVE months(month_no) AS (SELECT 1 UNION ALL SELECT month_no+1 FROM months WHERE month_no<12) SELECT m.month_no month,COUNT(a.application_id) total FROM months m LEFT JOIN stay_application a ON YEAR(a.created_at)=YEAR(CURRENT_DATE()) AND MONTH(a.created_at)=m.month_no AND a.current_status<>'DRAFT' GROUP BY m.month_no ORDER BY m.month_no");
 }
 public Map<String,Object> dashboardAnalysis(CurrentUser u,String period,String batchId,String buildingId){
  role(u,"ADMIN");
  StringBuilder where=new StringBuilder(" WHERE a.current_status IN ('APPROVED','COMPLETED')");
  List<Object> args=new ArrayList<>();
  if("year1".equals(period)){where.append(" AND b.open_end_date>=DATE_SUB(CURRENT_DATE(),INTERVAL 1 YEAR)");}
  else if("year10".equals(period)){where.append(" AND b.open_end_date>=DATE_SUB(CURRENT_DATE(),INTERVAL 10 YEAR)");}
  if(batchId!=null&&!batchId.isBlank()&&!"all".equals(batchId)){where.append(" AND b.batch_id=?");args.add(id(batchId));}
  if(buildingId!=null&&!buildingId.isBlank()){where.append(" AND a.building_id=?");args.add(id(buildingId));}
  String group="all".equals(batchId)?("all".equals(period)?"CAST(b.academic_year AS CHAR)":"CONCAT(b.academic_year,' ',b.batch_name)"):"b.batch_name";
  var rows=db.rows("SELECT "+group+" series,COALESCE(bd.building_name,'未分配楼栋') label,COUNT(DISTINCT a.student_id) total FROM stay_application a JOIN stay_batch b ON b.batch_id=a.batch_id LEFT JOIN building bd ON bd.building_id=a.building_id"+where+" GROUP BY series,label ORDER BY series,label",args.toArray());
  return Map.of("period",period,"batchId",batchId==null?"":batchId,"rows",rows);
 }
  public List<Map<String,Object>> list(CurrentUser u){role(u,"STUDENT","DORM_MANAGER","ADMIN");String filter=u.role().equals("STUDENT")?"a.student_id="+u.id():scope.buildingFilter(u,"a.building_id")+" AND a.version_id IS NOT NULL";var rows=db.rows("SELECT a.*,s.student_no,sp.major_name,b.academic_year,b.vacation_type,b.open_start_date,b.open_end_date FROM v_stay_application a JOIN stay_batch b ON b.batch_id=a.batch_id JOIN student s ON s.student_id=a.student_id LEFT JOIN v_student_profile sp ON sp.student_id=a.student_id WHERE "+filter+" ORDER BY a.updated_at DESC");for(var a:rows){if(u.role().equals("STUDENT")&&Set.of("DRAFT","PENDING_REVIEW","PENDING_EDIT").contains(a.get("current_status"))){var versions=db.rows("SELECT * FROM stay_version WHERE application_id=? ORDER BY version_id DESC LIMIT 1",a.get("application_id"));if(!versions.isEmpty()){a.put("version_id",versions.get(0).get("version_id"));a.put("reason",versions.get(0).get("reason"));}}Object versionId=a.get("version_id");a.put("dateRanges",versionId==null?List.of():db.rows("SELECT start_date startDate,end_date endDate FROM stay_date_range WHERE version_id=? ORDER BY start_date",versionId));a.put("attachments",versionId==null?List.of():db.rows("SELECT f.file_id,f.original_name,f.content_type,f.size_bytes FROM stay_version_attachment x JOIN file_resource f ON f.file_id=x.file_id WHERE x.version_id=? ORDER BY f.original_name",versionId));a.put("reviews",db.rows("SELECT * FROM stay_review WHERE application_id=? ORDER BY review_id",a.get("application_id")));}return rows;}
 private Map<String,Object> locked(long application){return db.one("SELECT * FROM stay_application WHERE application_id=? FOR UPDATE",application);}
 private void access(CurrentUser u,Map<String,Object>a){if(u.role().equals("STUDENT")){if(id(a.get("student_id"))!=u.id())throw BizException.forbidden();}else scope.building(u,id(a.get("building_id")));}
 private Map<String,Object> batch(long batch){return db.one("SELECT * FROM stay_batch WHERE batch_id=?",batch);}
 private void mutable(Map<String,Object>a){require(Set.of("DRAFT","PENDING_REVIEW","PENDING_EDIT").contains(a.get("current_status")),"申请已锁定或归档，不能修改");LocalDateTime deadline;if("PENDING_EDIT".equals(a.get("current_status")))deadline=time(a.get("resubmit_deadline"));else deadline=time(db.one("SELECT application_deadline FROM stay_building_rule WHERE batch_id=? AND building_id=?",a.get("batch_id"),a.get("building_id")).get("application_deadline"));require(LocalDateTime.now().isBefore(deadline),"已超过允许提交时间");}
 public static List<Map<String,Object>> validateRanges(Object raw,LocalDate start,LocalDate end){
  require(raw instanceof List<?> && !((List<?>)raw).isEmpty(),"至少填写一个留宿时间段");List<Map<String,Object>> ranges=new ArrayList<>();
  for(Object x:(List<?>)raw){require(x instanceof Map<?,?>,"留宿日期格式无效");Map<?,?> r=(Map<?,?>)x;LocalDate a=date(r.get("startDate")),b=date(r.get("endDate"));require(!b.isBefore(a)&&!a.isBefore(start)&&!b.isAfter(end),"每个留宿时间段必须完全位于开放区间内");ranges.add(Map.of("startDate",a,"endDate",b));}
  ranges.sort(Comparator.comparing(x->(LocalDate)x.get("startDate")));for(int i=1;i<ranges.size();i++)require(((LocalDate)ranges.get(i).get("startDate")).isAfter((LocalDate)ranges.get(i-1).get("endDate")),"留宿时间段不可重叠，共享边界日也算重叠");return ranges;
 }
  private long version(CurrentUser u,long application,Map<String,Object>b,Map<String,Object>batch,boolean submit){var ranges=validateRanges(b.get("dateRanges"),date(batch.get("open_start_date")),date(batch.get("open_end_date")));long v=db.insert("INSERT INTO stay_version(application_id,reason,submitted_at) VALUES(?,?,?)",application,required(b,"reason"),submit?LocalDateTime.now():null);for(var r:ranges)db.update("INSERT INTO stay_date_range(version_id,start_date,end_date) VALUES(?,?,?)",v,r.get("startDate"),r.get("endDate"));if(b.get("fileIds") instanceof List<?> files){require(files.size()<=8,"最多上传8份留宿申请材料");for(Object raw:files){long fileId=id(raw);require(db.count("SELECT COUNT(*) FROM file_resource WHERE file_id=? AND uploader_user_id=?",fileId,u.id())==1,"留宿申请附件无效");db.update("INSERT INTO stay_version_attachment(version_id,file_id) VALUES(?,?)",v,fileId);}}return v;}
  @Transactional public Map<String,Object> save(CurrentUser u,Map<String,Object>b){role(u,"STUDENT");long batchId=id(b.get("batchId"));var batch=batch(batchId);require("OPEN".equals(batch.get("current_status")),"批次未开放");db.one("SELECT person_id FROM person WHERE person_id=? FOR UPDATE",u.id());var old=db.rows("SELECT * FROM stay_application WHERE batch_id=? AND student_id=? FOR UPDATE",batchId,u.id());long application;Map<String,Object>a;if(old.isEmpty()){var home=scope.accommodation(u.id());var rule=db.one("SELECT * FROM stay_building_rule WHERE batch_id=? AND building_id=?",batchId,home.get("building_id"));require(LocalDateTime.now().isBefore(time(rule.get("application_deadline"))),"已超过申请截止时间");application=db.insert("INSERT INTO stay_application(batch_id,student_id,building_id,current_status) VALUES(?,?,?,'DRAFT')",batchId,u.id(),home.get("building_id"));a=locked(application);}else{a=old.get(0);application=id(a.get("application_id"));mutable(a);}version(u,application,b,batch,false);db.update("UPDATE stay_application SET updated_at=NOW() WHERE application_id=?",application);db.log(u.id(),"stay","save",application);return Map.of("applicationId",application);}
  @Transactional public void submit(CurrentUser u,long application){role(u,"STUDENT");var a=locked(application);access(u,a);mutable(a);var batch=batch(id(a.get("batch_id")));require("OPEN".equals(batch.get("current_status")),"批次未开放");var v=db.one("SELECT * FROM stay_version WHERE application_id=? ORDER BY version_id DESC LIMIT 1",application);var ranges=db.rows("SELECT start_date startDate,end_date endDate FROM stay_date_range WHERE version_id=?",v.get("version_id"));validateRanges(ranges,date(batch.get("open_start_date")),date(batch.get("open_end_date")));require(db.count("SELECT COUNT(*) FROM stay_version_attachment WHERE version_id=?",v.get("version_id"))>0,"提交留宿申请至少上传一份附件");require(v.get("submitted_at")==null,"该版本已经提交");db.update("UPDATE stay_version SET submitted_at=NOW() WHERE version_id=?",v.get("version_id"));String next="PENDING_EDIT".equals(a.get("current_status"))?"UNDER_REVIEW":"PENDING_REVIEW";db.update("UPDATE stay_application SET current_status=? WHERE application_id=?",next,application);notice.managers(id(a.get("building_id")),"留宿申请已提交","申请编号："+application);db.log(u.id(),"stay","submit",application);}
  @Transactional public void withdraw(CurrentUser u,long application){role(u,"STUDENT");var a=locked(application);access(u,a);require("PENDING_REVIEW".equals(a.get("current_status")),"只能撤回尚未锁定的待审核申请");mutable(a);var previous=db.one("SELECT * FROM stay_version WHERE application_id=? ORDER BY version_id DESC LIMIT 1",application);long draft=db.insert("INSERT INTO stay_version(application_id,reason) VALUES(?,?)",application,previous.get("reason"));db.update("INSERT INTO stay_date_range(version_id,start_date,end_date) SELECT ?,start_date,end_date FROM stay_date_range WHERE version_id=?",draft,previous.get("version_id"));db.update("INSERT IGNORE INTO stay_version_attachment(version_id,file_id) SELECT ?,file_id FROM stay_version_attachment WHERE version_id=?",draft,previous.get("version_id"));db.update("UPDATE stay_application SET current_status='DRAFT' WHERE application_id=?",application);db.log(u.id(),"stay","withdraw",application);}
 @Transactional public void lock(CurrentUser u,long application,boolean lock){role(u,"DORM_MANAGER");var a=locked(application);access(u,a);if(lock){require("PENDING_REVIEW".equals(a.get("current_status")),"只能锁定已提交待审核申请");db.update("UPDATE stay_application SET current_status='UNDER_REVIEW' WHERE application_id=?",application);}else{require("UNDER_REVIEW".equals(a.get("current_status"))&&a.get("resubmit_deadline")==null,"当前申请不允许普通解锁");var r=db.one("SELECT application_deadline FROM stay_building_rule WHERE batch_id=? AND building_id=?",a.get("batch_id"),a.get("building_id"));require(time(r.get("application_deadline")).isAfter(LocalDateTime.now()),"截止后不能通过解锁绕过期限，请使用逾期补录");db.update("UPDATE stay_application SET current_status='PENDING_REVIEW' WHERE application_id=?",application);}db.log(u.id(),"stay",lock?"lock":"unlock",application);}
 @Transactional public void review(CurrentUser u,long application,Map<String,Object>b){role(u,"DORM_MANAGER","ADMIN");var a=locked(application);access(u,a);Set<String> reviewable=u.role().equals("ADMIN")?Set.of("PENDING_REVIEW","UNDER_REVIEW"):Set.of("UNDER_REVIEW");require(reviewable.contains(a.get("current_status")),"当前申请状态不允许审核");if(a.get("resubmit_deadline")!=null)require(!time(a.get("resubmit_deadline")).isAfter(LocalDateTime.now()),"请在重交截止后统一复审");boolean pass=flag(b,"pass");String reason=pass?text(b,"reason"):required(b,"reason");LocalDateTime deadline=pass?null:time(b.get("resubmitDeadline"));if(!pass)require(deadline.isAfter(LocalDateTime.now()),"重交截止时间必须晚于当前时间");var v=db.one("SELECT version_id FROM stay_version WHERE application_id=? AND submitted_at IS NOT NULL ORDER BY version_id DESC LIMIT 1",application);if(pass){var batch=batch(id(a.get("batch_id")));validateRanges(db.rows("SELECT start_date startDate,end_date endDate FROM stay_date_range WHERE version_id=?",v.get("version_id")),date(batch.get("open_start_date")),date(batch.get("open_end_date")));}db.update("INSERT INTO stay_review(application_id,version_id,reviewer_user_id,result,reason) VALUES(?,?,?,?,?)",application,v.get("version_id"),u.id(),pass?"APPROVED":"RETURNED",reason);db.update("UPDATE stay_application SET current_status=?,review_reason=?,reviewer_user_id=?,reviewed_at=NOW(),resubmit_deadline=? WHERE application_id=?",pass?"APPROVED":"PENDING_EDIT",reason,u.id(),deadline,application);notice.send(List.of(id(a.get("student_id"))),"留宿审核结果",pass?"留宿申请已通过":"请修改："+reason+"；重交截止："+deadline);db.log(u.id(),"stay","review",application);}
 @Transactional public Map<String,Object> configure(CurrentUser u,Long batchId,Map<String,Object>b){
  role(u,"ADMIN");LocalDate start=date(b.get("openStartDate")),end=date(b.get("openEndDate"));require(!end.isBefore(start),"开放区间无效");long year=id(b.get("academicYear"));require(year>=2000&&year<=9999,"年份无效");String vacation=required(b,"vacationType");require(Set.of("SUMMER","WINTER").contains(vacation),"假期类型无效");LocalDateTime deadline=time(b.get("applicationDeadline"));require(!deadline.isBefore(start.atStartOfDay())&&deadline.isBefore(end.plusDays(1).atStartOfDay()),"申请截止时间必须在开放区间内");
  long batch;
  if(batchId==null)batch=db.insert("INSERT INTO stay_batch(batch_code,batch_name,academic_year,vacation_type,open_start_date,open_end_date,application_deadline,instructions,current_status) VALUES(?,?,?,?,?,?,?,?, 'DRAFT')",required(b,"batchCode"),required(b,"batchName"),year,vacation,start,end,deadline,required(b,"instructions"));
  else{
   batch=batchId;var original=db.one("SELECT * FROM stay_batch WHERE batch_id=? FOR UPDATE",batch);
   db.update("UPDATE stay_batch SET batch_name=?,academic_year=?,vacation_type=?,open_start_date=?,open_end_date=?,application_deadline=?,instructions=? WHERE batch_id=?",required(b,"batchName"),year,vacation,start,end,deadline,required(b,"instructions"),batch);
   if("OPEN".equals(original.get("current_status")))db.update("UPDATE stay_building_rule SET application_deadline=? WHERE batch_id=?",deadline,batch);
  }
  if(b.get("materialFileIds") instanceof List<?> ids)replaceMaterials(u,batch,ids);
  db.log(u.id(),"stay","configure_batch",batch);return Map.of("batchId",batch);
 }
 private void replaceMaterials(CurrentUser u,long batchId,List<?> raw){
  LinkedHashSet<Long> requested=new LinkedHashSet<>();for(Object value:raw)requested.add(id(value));
  var existing=db.rows("SELECT file_id FROM stay_batch_material WHERE batch_id=?",batchId);Set<Long> existingIds=new HashSet<>();for(var row:existing)existingIds.add(id(row.get("file_id")));
  for(long fileId:requested)if(!existingIds.contains(fileId)&&db.count("SELECT COUNT(*) FROM file_resource WHERE file_id=? AND uploader_user_id=?",fileId,u.id())==0)throw BizException.forbidden();
  for(long fileId:existingIds)if(!requested.contains(fileId))db.update("DELETE FROM stay_batch_material WHERE batch_id=? AND file_id=?",batchId,fileId);
  for(long fileId:requested)if(!existingIds.contains(fileId))db.update("INSERT INTO stay_batch_material(batch_id,file_id) VALUES(?,?)",batchId,fileId);
 }
 @Transactional public void attachMaterial(CurrentUser u,long batchId,long fileId){role(u,"ADMIN");db.one("SELECT batch_id FROM stay_batch WHERE batch_id=?",batchId);if(db.count("SELECT COUNT(*) FROM file_resource WHERE file_id=? AND uploader_user_id=?",fileId,u.id())==0)throw BizException.forbidden();db.update("INSERT IGNORE INTO stay_batch_material(batch_id,file_id) VALUES(?,?)",batchId,fileId);}
 @Transactional public void removeMaterial(CurrentUser u,long batchId,long fileId){role(u,"ADMIN");db.update("DELETE FROM stay_batch_material WHERE batch_id=? AND file_id=?",batchId,fileId);}
 @Transactional public void publish(CurrentUser u,long batchId,Map<String,Object>b){
  if(u.role().equals("ADMIN")){
   var batch=db.one("SELECT * FROM stay_batch WHERE batch_id=? FOR UPDATE",batchId);require("DRAFT".equals(batch.get("current_status")),"该留宿批次已发布");LocalDateTime deadline=time(b.get("applicationDeadline"));require(deadline.isAfter(LocalDateTime.now())&&deadline.isBefore(date(batch.get("open_end_date")).plusDays(1).atStartOfDay()),"申请截止时间必须在当前时间之后、开放区间结束之前");
   for(var building:db.rows("SELECT building_id FROM building ORDER BY building_id"))db.update("INSERT INTO stay_building_rule(batch_id,building_id,application_deadline,auto_lock) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE application_deadline=VALUES(application_deadline),auto_lock=VALUES(auto_lock)",batchId,building.get("building_id"),deadline,flag(b,"autoLock"));
   db.update("UPDATE stay_batch SET current_status='OPEN',application_deadline=? WHERE batch_id=?",deadline,batchId);db.log(u.id(),"stay","publish_schoolwide",batchId);return;
  }
  role(u,"DORM_MANAGER");long building=id(b.get("buildingId"));scope.building(u,building);var batch=batch(batchId);require("OPEN".equals(batch.get("current_status")),"该留宿批次尚未开放");LocalDateTime deadline=time(b.get("applicationDeadline"));require(deadline.isAfter(LocalDateTime.now())&&deadline.isBefore(date(batch.get("open_end_date")).plusDays(1).atStartOfDay()),"截止时间必须在当前时间之后、开放区间结束之前");db.update("INSERT INTO stay_building_rule(batch_id,building_id,application_deadline,auto_lock) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE application_deadline=VALUES(application_deadline),auto_lock=VALUES(auto_lock)",batchId,building,deadline,flag(b,"autoLock"));notice.send(db.rows("SELECT student_id FROM v_accommodation_current WHERE building_id=?",building).stream().map(x->id(x.get("student_id"))).toList(),"留宿申请已开放",batch.get("batch_name")+"；申请截止："+deadline);db.log(u.id(),"stay","publish",batchId);
 }
  @Transactional public Map<String,Object> supplement(CurrentUser u,Map<String,Object>b){role(u,"DORM_MANAGER","ADMIN");long student=id(b.get("studentId")),batchId=id(b.get("batchId"));db.one("SELECT person_id FROM person WHERE person_id=? FOR UPDATE",student);db.one("SELECT user_id FROM v_user_identity WHERE user_id=? AND role_code='STUDENT' AND enabled=1",student);var home=scope.accommodation(student);scope.building(u,id(home.get("building_id")));var batch=batch(batchId);require("OPEN".equals(batch.get("current_status")),"批次未开放");boolean admin=u.role().equals("ADMIN");if(!admin){var rule=db.one("SELECT application_deadline FROM stay_building_rule WHERE batch_id=? AND building_id=?",batchId,home.get("building_id"));require(!time(rule.get("application_deadline")).isAfter(LocalDateTime.now()),"未到截止时间，请由学生正常申请");}var old=db.rows("SELECT * FROM stay_application WHERE batch_id=? AND student_id=? FOR UPDATE",batchId,student);long a;if(old.isEmpty())a=db.insert("INSERT INTO stay_application(batch_id,student_id,building_id,source,current_status,reviewer_user_id,reviewed_at) VALUES(?,?,?,?,?,?,?)",batchId,student,home.get("building_id"),admin?"ADMIN_ADDED":"LATE",admin?"APPROVED":"UNDER_REVIEW",admin?u.id():null,admin?LocalDateTime.now():null);else{var original=old.get(0);require(Set.of("DRAFT","PENDING_EDIT","ARCHIVED").contains(original.get("current_status")),"已有有效申请，不能重复补录");a=id(original.get("application_id"));db.update("UPDATE stay_application SET source=?,current_status=?,reviewer_user_id=?,reviewed_at=?,resubmit_deadline=NULL,archived_at=NULL,archive_reason=NULL WHERE application_id=?",admin?"ADMIN_ADDED":"LATE",admin?"APPROVED":"UNDER_REVIEW",admin?u.id():null,admin?LocalDateTime.now():null,a);}long versionId=version(u,a,b,batch,true);if(admin)db.update("INSERT INTO stay_review(application_id,version_id,reviewer_user_id,result,reason) VALUES(?,?,?,'APPROVED','系统管理员人工补录，直接通过')",a,versionId,u.id());db.log(u.id(),"stay","supplement",a);return Map.of("applicationId",a,"currentStatus",admin?"APPROVED":"UNDER_REVIEW");}
 @Transactional public void deleteBatch(CurrentUser u,long batchId){role(u,"ADMIN");var row=db.one("SELECT current_status FROM stay_batch WHERE batch_id=? FOR UPDATE",batchId);require("DRAFT".equals(row.get("current_status")),"已发布的留宿批次不能删除");require(db.count("SELECT COUNT(*) FROM stay_application WHERE batch_id=?",batchId)==0,"留宿批次已有申请记录，不能删除");require(db.count("SELECT COUNT(*) FROM stay_building_rule WHERE batch_id=?",batchId)==0,"留宿批次已有开放规则，不能删除");db.update("DELETE FROM stay_batch_material WHERE batch_id=?",batchId);db.update("DELETE FROM stay_batch WHERE batch_id=?",batchId);db.log(u.id(),"stay","delete_batch",batchId);}
 @Transactional public void tick(){db.update("UPDATE stay_application a JOIN stay_building_rule r ON r.batch_id=a.batch_id AND r.building_id=a.building_id SET a.current_status='UNDER_REVIEW' WHERE a.current_status='PENDING_REVIEW' AND r.auto_lock=1 AND r.application_deadline<=NOW()");for(var a:db.rows("SELECT * FROM stay_application WHERE current_status='PENDING_EDIT' AND resubmit_deadline<=NOW() FOR UPDATE")){db.update("UPDATE stay_application SET current_status='ARCHIVED',archived_at=NOW(),archive_reason='未按期重新提交' WHERE application_id=?",a.get("application_id"));notice.send(List.of(id(a.get("student_id"))),"留宿申请归档","未按期重新提交，不计为已完成留宿");}for(var x:db.rows("SELECT application_id FROM v_stay_application WHERE current_status='APPROVED' AND end_date<CURRENT_DATE()")){var a=locked(id(x.get("application_id")));if(!"APPROVED".equals(a.get("current_status")))continue;db.update("UPDATE stay_application SET current_status='COMPLETED',archived_at=NOW(),archive_reason='留宿结束' WHERE application_id=?",a.get("application_id"));notice.send(List.of(id(a.get("student_id"))),"留宿已完成","申请已纳入历史留宿记录");}}
}
